operation.add:
// ProBG Services
$this->load->language('extension/module/probg_services');
$probg_services = array();
if ($this->user->hasPermission('access', 'extension/probg_services/service')) $probg_services[] = array('name'=>$this->language->get('text_menu_services'),'href'=>$this->url->link('extension/probg_services/service','user_token='.$this->session->data['user_token'],true),'children'=>array());
if ($this->user->hasPermission('access', 'extension/probg_services/category')) $probg_services[] = array('name'=>$this->language->get('text_menu_categories'),'href'=>$this->url->link('extension/probg_services/category','user_token='.$this->session->data['user_token'],true),'children'=>array());
if ($this->user->hasPermission('access', 'extension/probg_services/enquiry')) $probg_services[] = array('name'=>$this->language->get('text_menu_enquiries'),'href'=>$this->url->link('extension/probg_services/enquiry','user_token='.$this->session->data['user_token'],true),'children'=>array());
if ($this->user->hasPermission('access', 'extension/module/probg_services')) $probg_services[] = array('name'=>$this->language->get('text_menu_settings'),'href'=>$this->url->link('extension/module/probg_services','user_token='.$this->session->data['user_token'],true),'children'=>array());
if ($probg_services) $data['menus'][] = array('id'=>'menu-probg-services','icon'=>'fa-briefcase','name'=>$this->language->get('text_menu_module'),'href'=>'','children'=>$probg_services);

if ($data['route'] == 'extension/module/probg_services' && ($key == 'route' || $key == 'probg_service_category_id' || $key == 'probg_service_id')) {
    $probg_services_query = ($key == 'route') ? $value : $key . '=' . (int)$value;
    $probg_services_seo = $this->db->query("SELECT * FROM " . DB_PREFIX . "seo_url WHERE `query` = '" . $this->db->escape($probg_services_query) . "' AND store_id = '" . (int)$this->config->get('config_store_id') . "' AND language_id = '" . (int)$this->config->get('config_language_id') . "'");
    if ($probg_services_seo->num_rows && $probg_services_seo->row['keyword']) { $url .= '/' . $probg_services_seo->row['keyword']; unset($data[$key]); }
}
